import { RelicSkills } from '../skills/RelicSkills.js';

export class Player {
  constructor(game,x,y){this.game=game;this.x=x;this.y=y;this.radius=17;this.speed=230;this.hp=100;this.restore=0;this.invulnerable=0;this.keys=new Set();this.mouse={x,y,down:false};this.skills=new RelicSkills(this);this.bindInput()}
  bindInput(){window.addEventListener('keydown',e=>{this.keys.add(e.key.toLowerCase());if(e.key.toLowerCase()==='q')this.skills.cast('wedge')});window.addEventListener('keyup',e=>this.keys.delete(e.key.toLowerCase()));this.game.canvas.addEventListener('mousemove',e=>{const r=this.game.canvas.getBoundingClientRect();this.mouse.x=(e.clientX-r.left)*this.game.width/r.width;this.mouse.y=(e.clientY-r.top)*this.game.height/r.height});this.game.canvas.addEventListener('mousedown',e=>{if(e.button===2){e.preventDefault();this.skills.cast('onggi');this.mouse.down=true}});window.addEventListener('mouseup',()=>this.mouse.down=false);this.game.canvas.addEventListener('contextmenu',e=>e.preventDefault())}
  update(dt){const dx=(this.keys.has('d')?1:0)-(this.keys.has('a')?1:0),dy=(this.keys.has('s')?1:0)-(this.keys.has('w')?1:0),length=Math.hypot(dx,dy)||1;this.x+=dx/length*this.speed*dt;this.y+=dy/length*this.speed*dt;this.x=Math.max(58,Math.min(1222,this.x));this.y=Math.max(180,Math.min(640,this.y));if(this.keys.has(' ')||this.mouse.down)this.skills.cast('onggi');this.invulnerable=Math.max(0,this.invulnerable-dt);this.skills.update(dt)}
  damage(amount){if(this.invulnerable>0||this.skills.shield)return;this.hp=Math.max(0,this.hp-amount);this.invulnerable=.75;if(this.hp===0){this.hp=100;this.game.showMessage('시온이 복원대에서 깨어났습니다')}}
  draw(c){c.save();c.translate(this.x,this.y);if(this.invulnerable>0&&Math.floor(this.invulnerable*14)%2===0)c.globalAlpha=.35;c.fillStyle='#ead6aa';c.fillRect(-12,-15,24,30);c.fillStyle='#a33d32';c.fillRect(-15,-19,30,8);c.fillStyle='#2d3544';c.fillRect(-10,10,7,8);c.fillRect(3,10,7,8);const angle=Math.atan2(this.mouse.y-this.y,this.mouse.x-this.x);c.rotate(angle);c.fillStyle='#d6ad61';c.fillRect(9,-3,20,6);if(this.skills.shield){c.strokeStyle='#efc66f';c.lineWidth=4;c.beginPath();c.arc(0,0,27,-1.1,1.1);c.stroke()}c.restore()}
}
